import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ServalAndBonus solver = new ServalAndBonus();
        solver.solve(1, in, out);
        out.close();
    }

    static class ServalAndBonus {
        long MOD = 998244353;
        long[] inv = new long[5005];
        long[] pow = new long[5005];

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int K = in.nextInt();
            long l = in.nextInt();
            long invL = MathUtils.inverse(l, MOD);
            for (int i = 1; i < inv.length; i++) {
                inv[i] = MathUtils.inverse(i, MOD);
            }
            pow[0] = 1;
            for (int i = 1; i < pow.length; i++) {
                pow[i] = pow[i - 1] * l;
                pow[i] %= MOD;
            }
            long invL2 = (invL * invL) % MOD;
            long res = 0;
            long[] poly = new long[]{l, -1};
            long[] other = new long[]{(l * l) % MOD, -2 * l, 2};
            long[] cur = new long[4050];
            cur[0] = 1;
            for (int i = 0; i < N; i++) {
                for (int j = cur.length - 2; j >= 0; j--) {
                    cur[j] = cur[j] * poly[0] + (j - 1 >= 0 ? cur[j - 1] * poly[1] : 0);
                    cur[j] = MathUtils.mod(cur[j], MOD);
                    cur[j + 1] = cur[j];
                    cur[j] = 0;
                }
            }
            long comb = 1;
            for (int i = N; i >= K; i--) {
                long now = 0;
                for (int j = 0; j < cur.length; j++) {
                    now += ((pow[j + 1] * inv[j + 1]) % MOD) * cur[j];
                    now = MathUtils.mod(now, MOD);
                }
                now *= MathUtils.binPow(2, i, MOD);
                now %= MOD;
                now *= comb;
                now %= MOD;
                res += now;
                if (res >= MOD) {
                    res -= MOD;
                }
                for (int j = cur.length - 1; j >= 0; j--) {
                    cur[j] = cur[j] * other[0];
                    for (int k = 1; k <= 2; k++) {
                        if (j - k >= 0) {
                            cur[j] += cur[j - k] * other[k];
                        }
                    }
                    cur[j] = MathUtils.mod(cur[j], MOD);
                }
                long val = cur[cur.length - 1];
                for (int j = cur.length - 1; j >= 1; j--) {
                    cur[j] = -val;
                    val = cur[j - 1] + l * val;
                    val = MathUtils.mod(val, MOD);
                }
                for (int j = 0; j < cur.length - 1; j++) {
                    if (j + 2 >= cur.length) {
                        cur[j] = 0;
                    } else {
                        cur[j] = cur[j + 2];
                    }
                }
                comb *= inv[N - i + 1];
                comb %= MOD;
                comb *= i;
                comb %= MOD;
            }
            res *= MathUtils.binPow(invL2, N, MOD);
            res %= MOD;
            out.println(res);
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }

    static class MathUtils {
        public static long inverse(long a, long mod) {
            long[] inv = extended_gcd(a, mod);
            if (inv[0] != 1) {
                return 0;
            } else {
                return (inv[1] + 2 * mod) % mod;
            }
        }

        public static long[] extended_gcd(long a, long b) {
            //three numbers, first is gcd, second is x, third is y
            if (a == 0) {
                return new long[]{b, 0, 1};
            }
            long[] next = extended_gcd(b % a, a);
            long tempX = next[1];
            next[1] = next[2] - (b / a) * next[1];
            next[2] = tempX;
            return next;
        }

        public static long binPow(long b, long p, long mod) {
            long res = 1;
            while (p > 0) {
                if ((p & 1) == 1) {
                    res *= b;
                    res %= mod;
                }
                b = b * b;
                p >>= 1;
                b %= mod;
            }
            return res;
        }

        public static long mod(long a, long mod) {
            return (a + (Math.abs(a) + mod - 1) / mod * mod) % mod;
        }

    }
}


